    # consecutive occurrences of the same foreground color.
    for r in range(h):
        for color in marks:
            pos = [c for c in range(w) if grid[r][c] == color]
            for a, b in zip(pos, pos[1:]):
                if 1 <= b-a-1 <= 3 and all(grid[r][c] == bg for c in range(a+1, b)):
                    for c in range(a+1, b):
                        out[r][c] = bridge
