def transform(grid):
    h, w = len(grid), len(grid[0])
    row_lines = [r for r in range(h) if len(set(grid[r])) == 1]
    col_lines = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def spans(n, lines):
        out, start = [], 0
        for x in lines:
            if start < x:
                out.append((start, x))
            start = x + 1
        if start < n:
            out.append((start, n))
        return out

    rs, cs = spans(h, row_lines), spans(w, col_lines)
    if not rs or not cs:
        return [row[:] for row in grid]
    # The most frequent non-divider color is the tile background. Choose the
    # tile with the most non-background cells as the pattern to repeat.
    div_colors = {grid[r][0] for r in row_lines} | {grid[0][c] for c in col_lines}
    counts = Counter(v for row in grid for v in row if v not in div_colors)
    bg = counts.most_common(1)[0][0] if counts else 0
    tiles = [(r0, r1, c0, c1) for r0, r1 in rs for c0, c1 in cs]
    def score(t):
        r0, r1, c0, c1 = t
        return sum(grid[r][c] != bg for r in range(r0, r1) for c in range(c0, c1))
    src = max(tiles, key=score)
    sr0, sr1, sc0, sc1 = src
    pattern = [row[sc0:sc1] for row in grid[sr0:sr1]]
    out = [row[:] for row in grid]
    for r0, r1, c0, c1 in tiles:
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = pattern[(r-r0) % len(pattern)][(c-c0) % len(pattern[0])]
    return out

