def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    background = counts.most_common(1)[0][0]
    row_lines = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background]
    col_lines = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background]

    def spans(n, lines):
        out, start = [], 0
        for x in lines:
            if start < x:
                out.append((start, x))
            start = x + 1
        if start < n:
            out.append((start, n))
        return out

    rs, cs = spans(h, row_lines), spans(w, col_lines)
    tiles = [(r0, r1, c0, c1) for r0, r1 in rs for c0, c1 in cs]
    if not tiles:
        return [row[:] for row in grid]
    src = max(tiles, key=lambda t: sum(grid[r][c] != background for r in range(t[0], t[1]) for c in range(t[2], t[3])))
    r0, r1, c0, c1 = src
    pattern = [row[c0:c1] for row in grid[r0:r1]]
    out = [row[:] for row in grid]
    for a, b, x, y in tiles:
        for r in range(a, b):
            for c in range(x, y):
                out[r][c] = pattern[(r-a) % len(pattern)][(c-x) % len(pattern[0])]
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    if not cells:
        return [row[:] for row in grid]
    colors = sorted({v for _, _, v in cells})

    # The input marks colored lines along one coordinate family. Choose the
    # family in which each color has the strongest concentration on a line.
    features = {
        'row': lambda r, c: r,
        'col': lambda r, c: c,
        'sum': lambda r, c: r + c,
        'diff': lambda r, c: r - c,
    }
    scores = {}
    for name, keyfn in features.items():
        counts = {}
        for r, c, v in cells:
            k = (v, keyfn(r, c))
            counts[k] = counts.get(k, 0) + 1
        scores[name] = sum(max(counts.get((v, k), 0) for k in {keyfn(r,c) for r,c,x in cells if x == v}) for v in colors)
    mode = max(features, key=lambda name: scores[name])
    keyfn = features[mode]
    period = len(colors)
    residue_to_color = {}
    for r, c, v in cells:
        residue = keyfn(r, c) % period
        if residue in residue_to_color and residue_to_color[residue] != v:
            # Keep the color supported by the greatest number of markers.
            pass
        residue_to_color[residue] = v
    # Resolve any collisions robustly by majority vote.
    votes = {}
    for r, c, v in cells:
        residue = keyfn(r, c) % period
        votes.setdefault(residue, {})[v] = votes.setdefault(residue, {}).get(v, 0) + 1
    residue_to_color = {k: max(v.items(), key=lambda item: item[1])[0] for k, v in votes.items()}
    return [[residue_to_color[keyfn(r, c) % period] for c in range(w)] for r in range(h)]

from collections import Counter, defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    marks = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    if not marks:
        return [row[:] for row in grid]
    colors = set(v for _, _, v in marks)
    period = len(colors)
    funcs = {
        'row': lambda r, c: r,
        'col': lambda r, c: c,
        'sum': lambda r, c: r + c,
        'diff': lambda r, c: r - c,
    }
    # Detect the family of parallel lines on which the markers lie.
    scores = {}
    for name, f in funcs.items():
        groups = defaultdict(Counter)
        for r, c, v in marks:
            groups[v][f(r, c)] += 1
        scores[name] = sum(max(g.values()) for g in groups.values())
    key = funcs[max(scores, key=scores.get)]
    votes = defaultdict(Counter)
    for r, c, v in marks:
        votes[key(r, c) % period][v] += 1
    phase_colors = {phase: counts.most_common(1)[0][0] for phase, counts in votes.items()}
    # All phases are represented by the marker colors in these tasks; if a
    # phase is absent, continue the observed phase cycle deterministically.
    known = sorted(phase_colors)
    for p in range(period):
        if p not in phase_colors:
            nearest = min(known, key=lambda q: (p-q) % period)
            phase_colors[p] = phase_colors[nearest]
    return [[phase_colors[key(r, c) % period] for c in range(w)] for r in range(h)]

