    marks = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    if not marks:
        return [row[:] for row in grid]
    colors = set(v for _, _, v in marks)
    period = len(colors)
    funcs = {
        'row': lambda r, c: r,
        'col': lambda r, c: c,
        'sum': lambda r, c: r + c,
        'diff': lambda r, c: r - c,
    }
    scores = {}
    for name, f in funcs.items():
        groups = defaultdict(Counter)
        for r, c, v in marks:
            groups[v][f(r, c)] += 1
        scores[name] = sum(max(g.values()) for g in groups.values())
    mode = max(scores, key=scores.get)
    key = funcs[mode]
    votes = defaultdict(Counter)
    for r, c, v in marks:
        votes[key(r, c) % period][v] += 1
    phase_colors = {phase: counts.most_common(1)[0][0] for phase, counts in votes.items()}
    known = sorted(phase_colors)
    for p in range(period):
        if p not in phase_colors:
            nearest = min(known, key=lambda q: (p-q) % period)
            phase_colors[p] = phase_colors[nearest]
    # Horizontal input bands encode row stripes. Diagonal clues encode
    # the ordered colors of a horizontal repeating sequence.
    outkey = (lambda r, c: r) if mode == 'row' else (lambda r, c: c)
    return [[phase_colors[outkey(r, c) % period] for c in range(w)] for r in range(h)]

def transform(grid):
    h, w = len(grid), len(grid[0])
    refs = [(r, row[0]) for r, row in enumerate(grid)
            if row[0] != 0 and all(x == row[0] for x in row)]
    if not refs:
        return [row[:] for row in grid]

    # The solid rows are samples of a repeating horizontal stripe sequence.
    # Use the shortest period that assigns each sampled row a consistent phase.
    period = next((p for p in range(1, h + 1)
                   if all(a != b or (r1 - r2) % p != 0
                          for i, (r1, a) in enumerate(refs)
                          for r2, b in refs[i + 1:])), h)
    phases = {}
    for r, color in refs:
