from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); q=deque()
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c)); comp=[]
                while q:
                    x,y=q.popleft(); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<h and 0<=ny<w and grid[nx][ny]==bg and (nx,ny) not in seen:
                            seen.add((nx,ny)); q.append((nx,ny))
                # Paint components fully enclosed by foreground; the boundary may close them too.
                # Keep components that reach a broad, open portion of an edge as exterior.
                edge_cells=[(x,y) for x,y in comp if x in (0,h-1) or y in (0,w-1)]
                if not edge_cells:
                    for x,y in comp: grid[x][y]=4
                elif len(edge_cells)<=max(2, len(comp)//5):
                    # Small isolated edge pockets are sealed by the drawing.
                    for x,y in comp: grid[x][y]=4
    return grid

