    for r in range(h):
        for c in range(w):
            if grid[r][c]!=bg or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); comp=[]
            while q:
                x,y=q.popleft(); comp.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<h and 0<=ny<w and grid[nx][ny]==bg and (nx,ny) not in seen:
                        seen.add((nx,ny)); q.append((nx,ny))
            comps.append(comp)
    out=[row[:] for row in grid]
    for comp in comps:
        edge=[(r,c) for r,c in comp if r in (0,h-1) or c in (0,w-1)]
        enclosed=not edge
        if edge:
            # A component touching a canvas edge is still enclosed when its
            # full edge run is capped by foreground at both ends.
            for side in range(4):
                if side==0: cells=sorted(c for r,c in edge if r==0)
                elif side==1: cells=sorted(c for r,c in edge if r==h-1)
                elif side==2: cells=sorted(r for r,c in edge if c==0)
                else: cells=sorted(r for r,c in edge if c==w-1)
                if not cells: continue
                lo,hi=cells[0],cells[-1]
                if side==0: a=(0,lo-1); b=(0,hi+1); valid=lo>0 and hi<w-1 and grid[a[0]][a[1]]!=bg and grid[b[0]][b[1]]!=bg
                elif side==1: a=(h-1,lo-1); b=(h-1,hi+1); valid=lo>0 and hi<w-1 and grid[a[0]][a[1]]!=bg and grid[b[0]][b[1]]!=bg
