    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    cells = defaultdict(set)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                cells[grid[r][c]].add((r, c))
    rays = set()
    for color, pts in cells.items():
        other = [p for col, ps in cells.items() if col != color for p in ps]
        if not other:
            continue
        mr = sum(r for r, c in other) / len(other)
        mc = sum(c for r, c in other) / len(other)
        # Diagonal matched pairs project outward from the rest of the motif.
        for r, c in pts:
            for dr, dc in ((1, 1), (1, -1)):
                q = (r+dr, c+dc)
                if q not in pts or (r,c) > q:
                    continue
                if (r+q[0])/2 == mr and (c+q[1])/2 == mc:
                    continue
                choices = ((r,c,-dr,-dc),(q[0],q[1],dr,dc))
                er, ec, sr, sc = max(choices, key=lambda e:(e[0]+e[2]-mr)**2+(e[1]+e[3]-mc)**2)
                rays.add((color,er+sr,ec+sc,sr,sc))
        # If an isolated vertical duplicate is offset from the other markers,
        # extend its two ends diagonally outward from their center.
        if len(pts) == 2:
            a,b=sorted(pts)
            if a[1]==b[1] and b[0]==a[0]+1 and mc != a[1]:
                dc = -1 if mc > a[1] else 1
                rays.add((color,a[0]-1,a[1]+dc,-1,dc))
                rays.add((color,b[0]+1,b[1]+dc,1,dc))
    for color,r,c,dr,dc in rays:
        while 0<=r<h and 0<=c<w:
            if out[r][c] != bg:
                break
            out[r][c]=color
            r+=dr; c+=dc
    return out

