def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    cells = defaultdict(list)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                cells[grid[r][c]].append((r, c))

    rays = set()
    for color, pts in cells.items():
        other = [p for col, ps in cells.items() if col != color for p in ps]
        if not other:
            continue
        mr = sum(r for r, c in other) / len(other)
        mc = sum(c for r, c in other) / len(other)
        pts_set = set(pts)
        # A pair centered exactly on the other motif has no outward direction.
        for r, c in pts:
            for dr, dc in ((1, 1), (1, -1)):
                q = (r + dr, c + dc)
                if q not in pts_set or (r, c) > q:
                    continue
                # Extend the pair away from the centroid of the other-color motif.
                if (r + q[0]) / 2 == mr and (c + q[1]) / 2 == mc:
                    continue
                opts = ((r, c, -dr, -dc), (q[0], q[1], dr, dc))
                er, ec, sr, sc = max(opts, key=lambda e: (e[0] + e[2] - mr) ** 2 + (e[1] + e[3] - mc) ** 2)
                rays.add((color, er + sr, ec + sc, sr, sc))
    for color, r, c, dr, dc in rays:
        while 0 <= r < h and 0 <= c < w:
            if out[r][c] != bg:
                break
            out[r][c] = color
            r += dr
            c += dc
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    solid_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    solid_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}
    return [[2 if r in solid_rows or c in solid_cols else grid[r][c]
             for c in range(w)] for r in range(h)]

from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 8 and not seen[r][c]:
                seen[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 8 and not seen[r][c]:
                seen[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 8 and not seen[nr][nc]:
                seen[nr][nc] = True
                q.append((nr, nc))
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 and not seen[r][c]:
                out[r][c] = 7
    return out

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0 = min(y for y,x in comp); r1 = max(y for y,x in comp)
            c0 = min(x for y,x in comp); c1 = max(x for y,x in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            border = {(r0,x) for x in range(c0,c1+1)} | {(r1,x) for x in range(c0,c1+1)} | {(y,c0) for y in range(r0,r1+1)} | {(y,c1) for y in range(r0,r1+1)}
            if set(comp) != border:
                continue
            fill = 7 if ((r1-r0-1)*(c1-c0-1)) % 2 else 2
            for y in range(r0+1,r1):
                for x in range(c0+1,c1):
                    out[y][x] = fill
    return out

